async function writingFile(path, fileName, data) {
  return new Promise((resolve, reject) => {
    if (!existsSync(path)) {
      fs.mkdir(path, { recursive: true }, (err) => {
        if (err) {
          reject(err)
        }
      })
    }

    fs.writeFile(fileName, data, (err) => {
      if (err) {
        reject(err)
      }
      resolve('Success')
    })
  })
}
```

